"""Shell completion scripts generated by Click."""

from __future__ import annotations

from typing import cast

import click
from click.shell_completion import get_completion_class

from wok.errors import WokError

_SHELLS = {"bash", "zsh", "fish"}


def completion(shell: str, command: object) -> str:
    """Return Click's completion source for prog name `wok`."""
    normalized = shell.lower()
    if normalized not in _SHELLS:
        raise WokError(f"Unsupported shell `{shell}`. Expected bash, zsh, or fish.")
    completion_cls = get_completion_class(normalized)
    if completion_cls is None:
        raise WokError(f"Unsupported shell `{shell}`. Expected bash, zsh, or fish.")
    script = completion_cls(cast(click.Command, command), {}, "wok", "_WOK_COMPLETE")
    return script.source()
